import {$,$$,esc,icon,panelHeader} from './ui.js';
import {taskKey} from './domain.js';
export function taskSummary(snapshot,tasks){let total=0,completed=0;for(const n of snapshot.nodes){for(let i=0;i<n.tasks.length;i++){total++;if(tasks[taskKey(snapshot.version,n.id,i)]===true)completed++}}return{total,completed,pending:total-completed}}
export function updateNavigation(snapshot,ui,store){
 const stats=taskSummary(snapshot,store.tasks);
 $('#nav-nodes').textContent=snapshot.nodes.length;$('#nav-tasks').textContent=stats.pending;$('#nav-projects').textContent=snapshot.nodes.filter(n=>n.kind==='project').length;
 $$('[aria-label="主导航"] .sidebar-nav').forEach(b=>{const active=b.dataset.action===(ui.panel==='tasks'?'tasks':ui.panel==='projects'?'projects':'home');b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 const recents=(store.recents?.length?store.recents:['cicd','api']).filter(id=>snapshot.nodes.some(n=>n.id===id)).slice(0,3);
 $('#recent-nodes').innerHTML=recents.map(id=>{const n=snapshot.nodes.find(n=>n.id===id);return`<button class="recent-node" data-node="${n.id}"><i class="recent-dot recent-level-${n.level}"></i><span>${esc(n.title)}</span><span>↗</span></button>`}).join('')||'<p class="recent-empty">点击节点，开始探索。</p>';
 const collapsed=store.navigationCollapsed===true;document.body.classList.toggle('navigation-collapsed',collapsed);const toggle=$('.collapse-button');toggle.textContent=collapsed?'›':'‹';toggle.setAttribute('aria-label',collapsed?'展开导航':'收起导航');toggle.title=collapsed?'展开导航':'收起导航';
}
export function renderTaskQueue(snapshot,ui,store){
 const stats=taskSummary(snapshot,store.tasks),readonly=ui.version!==null;
 const groups=snapshot.nodes.map(n=>({n,items:n.tasks.map((title,i)=>({title,i,done:store.tasks[taskKey(snapshot.version,n.id,i)]===true})).filter(t=>ui.taskScope==='all'||!t.done)})).filter(g=>g.items.length);
 return`${panelHeader('LEARNING QUEUE','学习清单')}<div class="panel-content"><div class="queue-overview"><strong>${stats.pending}<small>个待完成练习</small></strong><span>${stats.completed} / ${stats.total} 已完成</span></div><p class="panel-intro">从能力节点汇总的小任务。完成练习只记录进度，不自动提升能力等级。</p>${readonly?'<div class="notice">当前为历史快照，只能查看当时的练习进度。</div>':''}<div class="segmented"><button data-task-scope="pending" class="${ui.taskScope==='pending'?'active':''}">待完成</button><button data-task-scope="all" class="${ui.taskScope==='all'?'active':''}">全部练习</button></div>${groups.map(({n,items})=>`<section class="queue-group"><button class="queue-node-link" data-node="${n.id}" data-node-tab="exercise">${icon(n.icon)}<span>${esc(n.title)}</span><span>↗</span></button>${items.map(t=>`<label class="task-row"><input type="checkbox" data-task="${t.i}" data-task-node="${n.id}" ${t.done?'checked':''} ${readonly?'disabled':''}><span>${esc(t.title)}</span></label>`).join('')}</section>`).join('')||`<div class="sync-complete">${icon('check')}<h3>这一轮练习已完成。</h3><p>可以切到「全部练习」复查，或回到能力树继续探索。</p></div>`}</div>`;
}
export function renderProjectIndex(snapshot,mode){const projects=snapshot.nodes.filter(n=>n.kind==='project');return`${panelHeader('PROJECT EVIDENCE','项目证据')}<div class="panel-content"><p class="panel-intro">把做过的事连接到能力，留下可核对的记录。${mode==='server'||snapshot.sources.some(s=>!s.fictional)?'资料陈述和验证结果分别记录。':'这里全部为虚构示例项目。'}</p>${projects.map((n,i)=>`<article class="project-evidence project-index-card"><span class="overline">PROJECT / 0${i+1}</span><div class="card-title"><h3>${esc(n.title)}</h3><span class="stage-tag">${n.stage}</span></div><p>${esc(n.summary)}</p><div class="project-index-meta"><span>${n.evidence.length} 份示例记录</span><span>${n.refs.length} 条来源</span></div><div class="chips">${n.prereqs.map(id=>`<button data-node="${id}">${esc(snapshot.nodes.find(v=>v.id===id).title)} ↗</button>`).join('')}</div><button class="outline-button" data-node="${n.id}" data-node-tab="practice">进入项目证据 ↗</button></article>`).join('')}<div class="notice warning">讨论、计划、执行、待验证、已验证、已上线分别记录，不因添加一条讨论而推进阶段。</div></div>`}
